const fallback={schema_version:4,status_visual_pack:'AUTO',theme:{preset:'modern',primary:'#166534',secondary:'#111827',accent:'#14b8a6',background:'#f8fafc',surface:'#ffffff',text:'#172033',muted_text:'#667085',success:'#15803d',danger:'#b42318',radius:'medium',card_style:'clean',button_style:'solid',density:'comfortable'},typography:{preset:'SYSTEM_MINIMAL',heading_scale:'normal',body_scale:'normal',letter_spacing:'normal',button_case:'none'},layout:{header:'logo_left',hero:'split',categories:'cards',product_grid:'four',product_card:'standard',mobile_nav:'standard'},branding:{use_internal_name:false,store_name:'',announcement:'',hero_title:'',hero_subtitle:'',logo_url:'',favicon_url:''},seo:{title:'',description:'',social_image_url:''},responsive:{product_columns:{desktop:4,tablet:3,mobile:2},hero_media_position:{desktop:'right',tablet:'right',mobile:'below'}},product_detail:{gallery_style:'thumbnails',buy_box_style:'sticky',mobile_buy_bar:true,related_products:{enabled:true,limit:4},visibility:{category:true,discount:true,description:true,support:true},info_blocks:['availability','fulfillment','options']},navigation:['home','explore','cart','orders','profile'],home:{sections:[{id:'hero',type:'hero',enabled:true,title:'',body:'',image_url:'',video_url:'',poster_url:'',product_ref:'',cta_label:'',cta_path:'',limit:8,slides:[]},{id:'categories',type:'categories',enabled:true,title:'',body:'',image_url:'',video_url:'',poster_url:'',product_ref:'',cta_label:'',cta_path:'',limit:8,slides:[]},{id:'featured',type:'featured_products',enabled:true,title:'',body:'',image_url:'',video_url:'',poster_url:'',product_ref:'',cta_label:'',cta_path:'',limit:8,slides:[]}]},features:{search:true,promotions:true,support:true,ratings:false,stock_status:true,quick_add:false}};
const CUSTOMER_WEB_BASE=(import.meta.env.VITE_LUKE_SHOP_CUSTOMER_WEB_BASE_URL||'http://localhost:4174').replace(/\/$/,'');
