const sectionLibrary=[['hero','Hero','Campaign headline, media and CTA'],['hero_slider','Hero slider','Up to six rotating campaign slides'],['categories','Categories','Category discovery cards or rail'],['featured_products','Featured products','Curated product merchandising'],['promotion_banner','Promotion banner','Focused campaign promotion'],['new_arrivals','New arrivals','Newest published products'],['announcement_bar','Announcement bar','Compact storefront announcement']];
const navItems=['home','explore','cart','orders','profile'];
const productDetailBlocks=[['availability','Availability','Stock state and product type'],['fulfillment','Fulfillment','Available fulfillment modes'],['options','Options','Variant and modifier summary']];
const layouts={header:[['logo_left','Logo left'],['centered_logo','Centered logo'],['search_first','Search first'],['compact','Compact'],['transparent','Transparent over hero']],hero:[['split','Split image + text'],['full_width','Full-width campaign'],['slider','Slider'],['featured_product','Featured product'],['video','Video campaign'],['minimal','Minimal text']],categories:[['cards','Cards'],['circles','Circles'],['image_tiles','Image tiles'],['chips','Compact chips'],['horizontal','Horizontal rail']],product_grid:[['two','2 columns'],['three','3 columns'],['four','4 columns'],['editorial','Editorial'],['compact','Compact marketplace'],['horizontal','Horizontal rail']],product_card:[['standard','Standard'],['minimal','Minimal'],['soft','Soft'],['bold','Bold'],['technical','Technical'],['compact','Compact'],['quick_add','Quick add'],['editorial','Editorial']],mobile_nav:[['standard','Standard'],['ios','iOS style'],['compact','Compact']]};
const themeFields=[['primary','Primary'],['secondary','Secondary'],['accent','Accent'],['background','Background'],['surface','Surface'],['text','Text'],['muted_text','Muted text'],['success','Success'],['danger','Danger']];
const designerPanels=[['store','Store identity','◎'],['header','Header','☰'],['templates','Templates','▧'],['theme','Theme','◐'],['typography','Typography','Aa'],['layout','Layout','⌘'],['productDetail','Product detail','◫'],['home','Home sections','≋'],['navigation','Navigation','↗'],['features','Features','✦'],['seo','Search & sharing','⌕'],['history','History','↶']];
const previewPages=[
 {key:'home',label:'Home',route:'/',group:'Storefront',icon:'⌂',description:'Homepage sections, campaigns and discovery.'},
 {key:'explore',label:'Explore',route:'/explore',group:'Storefront',icon:'▦',description:'Catalog browsing and product discovery.'},
 {key:'product',label:'Product detail',route:'/product/:slug',group:'Commerce',icon:'◇',description:'Real published product detail preview.'},
 {key:'cart',label:'Cart',route:'/cart',group:'Commerce',icon:'◫',description:'Cart summary and next-step actions.'},
 {key:'checkout',label:'Checkout',route:'/checkout',group:'Commerce',icon:'✓',description:'Checkout and fulfillment presentation.'},
 {key:'orders',label:'Orders',route:'/orders',group:'Account',icon:'≡',description:'Customer order history and status.'},
 {key:'profile',label:'Profile',route:'/profile',group:'Account',icon:'○',description:'Customer account landing page.'},
 {key:'login',label:'Sign in',route:'/login',group:'Account',icon:'↪',description:'Customer authentication presentation.'},
];

function deepDiffPaths(a,b,prefix=''){
 if(a===b)return[];
 if(typeof a!=='object'||a===null||typeof b!=='object'||b===null||Array.isArray(a)||Array.isArray(b))return[prefix||'design'];
 const keys=new Set([...Object.keys(a||{}),...Object.keys(b||{})]);
 return[...keys].flatMap(k=>deepDiffPaths(a?.[k],b?.[k],prefix?`${prefix}.${k}`:k));
}
function templateLabel(row){const key=row?.base_template_key||row?.template_key;if(!key)return'Custom design';return row?.template_customized?`${key} · Customized`:key}
function pageForRoute(route){if(String(route||'').startsWith('/product/'))return{...previewPages.find(x=>x.key==='product'),route};return previewPages.find(x=>x.route===route)||previewPages[0]}
function saveLabel(saveState,dirty,savedAt){if(saveState==='error')return'Draft not saved';if(saveState==='saving')return'Saving…';if(dirty)return'Changes pending';if(savedAt)return`Saved ${savedAt.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;return'Draft synced'}
function changeGroup(path=''){const root=String(path).split('.')[0];return({branding:'Store identity',layout:'Layout',theme:'Theme',typography:'Typography',responsive:'Responsive',product_detail:'Product detail',home:'Home',navigation:'Navigation',features:'Features',seo:'Search & sharing',status_visual_pack:'Order visuals'})[root]||'Design'}
function groupedChanges(paths=[]){const map=new Map();for(const path of paths){const key=changeGroup(path);if(!map.has(key))map.set(key,[]);map.get(key).push(path)}return[...map.entries()].map(([label,items])=>({label,items}))}
function newSection(type='promotion_banner'){const label=sectionTypes.find(x=>x[0]===type)?.[1]||'Section';return{id:`section-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,type,enabled:true,title:type==='announcement_bar'?'Announcement':`New ${label}`,body:'',image_url:'',video_url:'',poster_url:'',product_ref:'',cta_label:['categories','featured_products','new_arrivals'].includes(type)?'Browse all':'Shop now',cta_path:'/explore',limit:8,slides:type==='hero_slider'?[{id:`slide-${Date.now()}`,title:'New slide',body:'',image_url:'',cta_label:'Explore',cta_path:'/explore'}]:[]}}

export function CustomerExperiencePage(){
 const{api,has,session}=useAuth();
 const[data,setData]=useState(null),[catalog,setCatalog]=useState({templates:[],typography_presets:[],status_visual_packs:[]}),[draft,setDraft]=useState(clone(fallback)),[err,setErr]=useState(null),[busy,setBusy]=useState(false),[toast,setToast]=useState(''),[dirty,setDirty]=useState(false),[savedAt,setSavedAt]=useState(null),[saveState,setSaveState]=useState('synced'),[active,setActive]=useState('home'),[templateChoice,setTemplateChoice]=useState(''),[keepContent,setKeepContent]=useState(true),[previewPath,setPreviewPath]=useState(''),[previewRoute,setPreviewRoute]=useState('/'),[previewMode,setPreviewMode]=useState('desktop'),[zoom,setZoom]=useState('fit'),[undoStack,setUndoStack]=useState([]),[redoStack,setRedoStack]=useState([]),[picker,setPicker]=useState(null),[dragIndex,setDragIndex]=useState(null),[selectedSectionId,setSelectedSectionId]=useState(''),[previewProducts,setPreviewProducts]=useState([]),[previewProductRef,setPreviewProductRef]=useState(''),[previewProductError,setPreviewProductError]=useState('');
 const revision=useRef(0),frames=useRef(new Set()),autosaveTimer=useRef(null),draftRef=useRef(draft),saveQueue=useRef(Promise.resolve());
 const load=useCallback(async()=>{setErr(null);try{const[d,c]=await Promise.all([api.request('/v1/merchant/customer-experience'),api.request('/v1/merchant/customer-experience/catalog')]);setData(d.data);setCatalog(c.data||{templates:[],typography_presets:[],status_visual_packs:[]});const next=clone(d.data.draft?.config||d.data.published?.config||fallback);setDraft(next);setTemplateChoice(d.data.draft?.base_template_key||d.data.draft?.template_key||d.data.published?.base_template_key||d.data.published?.template_key||'');setDirty(false);setSaveState('synced');setUndoStack([]);setRedoStack([]);setSelectedSectionId(next.home?.sections?.[0]?.id||'');return d.data}catch(e){setErr(e);return null}},[api]);
 const issuePreview=useCallback(async()=>{try{const r=await api.request('/v1/merchant/customer-experience/preview-token',{method:'POST',body:{}});setPreviewPath(r.data.preview_path||'')}catch(e){if(e?.code!=='CUSTOMER_EXPERIENCE_DRAFT_REQUIRED')setErr(e)}},[api]);
 useEffect(()=>{let alive=true;(async()=>{const d=await load();if(alive&&d?.draft)await issuePreview()})();return()=>{alive=false}},[load,issuePreview,session?.storeId]);
 useEffect(()=>{let alive=true;if(!has('catalog.read')){setPreviewProducts([]);setPreviewProductError('Product preview requires catalog.read permission.');return()=>{alive=false}}setPreviewProductError('');api.request('/v1/merchant/products',{query:{status:'PUBLISHED',limit:100}}).then(r=>{if(!alive)return;const rows=(r.data.products||[]).filter(x=>x.slug);setPreviewProducts(rows);setPreviewProductRef(current=>current&&rows.some(x=>x.public_id===current)?current:(rows[0]?.public_id||''))}).catch(e=>{if(alive)setPreviewProductError(e.message||'Unable to load published products')});return()=>{alive=false}},[api,has,session?.storeId]);
 useEffect(()=>{draftRef.current=draft},[draft]);
 useEffect(()=>{const before=e=>{if(dirty){e.preventDefault();e.returnValue=''}};window.addEventListener('beforeunload',before);return()=>window.removeEventListener('beforeunload',before)},[dirty]);
 const postPreview=useCallback((target=null,config=draft)=>{const msg={type:'luke-store-designer:config',config};if(target){try{target.postMessage(msg,CUSTOMER_WEB_ORIGIN)}catch{}return}for(const frame of frames.current){try{frame.contentWindow?.postMessage(msg,CUSTOMER_WEB_ORIGIN)}catch{}}},[draft]);
 useEffect(()=>{postPreview(null,draft)},[draft,postPreview]);
 useEffect(()=>{const listener=e=>{if(e.origin!==CUSTOMER_WEB_ORIGIN||e.data?.type!=='luke-store-designer:ready')return;postPreview(e.source,draft)};window.addEventListener('message',listener);return()=>window.removeEventListener('message',listener)},[draft,postPreview]);
 const commit=useCallback(next=>{setUndoStack(x=>[...x.slice(-39),clone(draft)]);setRedoStack([]);setDraft(next);revision.current+=1;setDirty(true)},[draft]);
 const mutate=useCallback(fn=>{const next=clone(draft);fn(next);commit(next)},[draft,commit]);
 const update=(area,key,value)=>mutate(next=>{next[area]={...(next[area]||{}),[key]:value}});
 const updateNested=(area,group,key,value)=>mutate(next=>{next[area]={...(next[area]||{}),[group]:{...(next[area]?.[group]||{}),[key]:value}}});
 const save=useCallback(({quiet=false}={})=>{if(!has('customer_experience.manage'))return Promise.resolve(false);const started=revision.current;const payload=clone(draftRef.current);setSaveState('saving');if(!quiet)setBusy(true);setErr(null);const job=async()=>{try{const r=await api.request('/v1/merchant/customer-experience/draft',{method:'PUT',body:{config:payload}});setData(prev=>prev?{...prev,draft:{...(prev.draft||{}),...(r.data.draft||{})}}:prev);if(started===revision.current){setDirty(false);setSavedAt(new Date());setSaveState('saved')}else setSaveState('pending');if(!previewPath)await issuePreview();if(!quiet)setToast('Draft saved');return true}catch(e){setSaveState('error');setErr(e);throw e}finally{if(!quiet)setBusy(false)}};saveQueue.current=saveQueue.current.catch(()=>{}).then(job);return saveQueue.current},[api,has,issuePreview,previewPath]);
 useEffect(()=>{clearTimeout(autosaveTimer.current);if(!dirty||!has('customer_experience.manage')||saveState==='error')return;setSaveState('pending');autosaveTimer.current=setTimeout(()=>save({quiet:true}).catch(()=>{}),900);return()=>clearTimeout(autosaveTimer.current)},[draft,dirty,has,save]);
 const undo=useCallback(()=>{if(!undoStack.length)return;const prev=undoStack[undoStack.length-1];setUndoStack(x=>x.slice(0,-1));setRedoStack(x=>[...x.slice(-39),clone(draft)]);setDraft(clone(prev));revision.current+=1;setDirty(true)},[undoStack,draft]);
 const redo=useCallback(()=>{if(!redoStack.length)return;const next=redoStack[redoStack.length-1];setRedoStack(x=>x.slice(0,-1));setUndoStack(x=>[...x.slice(-39),clone(draft)]);setDraft(clone(next));revision.current+=1;setDirty(true)},[redoStack,draft]);
 useEffect(()=>{const onKey=e=>{const mod=e.metaKey||e.ctrlKey;if(!mod)return;const tag=e.target?.tagName;const editing=['INPUT','TEXTAREA','SELECT'].includes(tag)||e.target?.isContentEditable;if(e.key.toLowerCase()==='s'&&has('customer_experience.manage')){e.preventDefault();save().catch(()=>{});return}if(editing)return;if(e.key.toLowerCase()==='z'&&e.shiftKey){e.preventDefault();redo();return}if(e.key.toLowerCase()==='z'){e.preventDefault();undo()}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[has,redo,save,undo]);
 const publish=async()=>{try{if(dirty)await save({quiet:true})}catch{return}const paths=deepDiffPaths(data?.published?.config||{},draft).filter(x=>x!=='schema_version');const groups=groupedChanges(paths);const summary=groups.slice(0,7).map(x=>`• ${x.label}: ${x.items.length}`).join('\n');if(!confirm(`Publish ${paths.length||1} storefront change${paths.length===1?'':'s'}?${summary?`\n\n${summary}`:''}`))return;setBusy(true);setErr(null);try{await api.request('/v1/merchant/customer-experience/publish',{method:'POST',body:{}});setToast('Customer experience published');const d=await load();if(d?.draft)await issuePreview()}catch(e){setErr(e)}finally{setBusy(false)}};
 const applyTemplate=async(mode='full')=>{if(!templateChoice)return;setBusy(true);setErr(null);try{const r=await api.request('/v1/merchant/customer-experience/apply-template',{method:'POST',body:{template_key:templateChoice,mode,keep_content:keepContent}});setDraft(clone(r.data.draft.config));revision.current+=1;setDirty(false);setSavedAt(new Date());setData(prev=>prev?{...prev,draft:r.data.draft}:prev);setSelectedSectionId(r.data.draft.config?.home?.sections?.[0]?.id||'');setToast(mode==='full'?'Template applied':`Template ${mode} applied`);await issuePreview()}catch(e){setErr(e)}finally{setBusy(false)}};
 const rollback=async version=>{if(!confirm(`Publish a new version based on version ${version}?`))return;setBusy(true);try{await api.request('/v1/merchant/customer-experience/rollback',{method:'POST',body:{version}});setToast(`Rolled back from version ${version}`);const d=await load();if(d?.draft)await issuePreview()}catch(e){setErr(e)}finally{setBusy(false)}};
 const choosePreviewProduct=ref=>{setPreviewProductRef(ref);const product=previewProducts.find(x=>x.public_id===ref);if(product?.slug){setPreviewRoute(`/product/${encodeURIComponent(product.slug)}`);setActive('productDetail')}};
 const previewProduct=previewProducts.find(x=>x.public_id===previewProductRef)||null;
 const productPreviewRoute=previewProduct?.slug?`/product/${encodeURIComponent(previewProduct.slug)}`:'';
 const openPublished=()=>data?.storefront_path&&window.open(`${CUSTOMER_WEB_BASE}${data.storefront_path}#${previewRoute}`,'_blank','noopener,noreferrer');
 const openDraftPreview=()=>previewPath&&window.open(`${CUSTOMER_WEB_BASE}${previewPath}#${previewRoute}`,'_blank','noopener,noreferrer');
 if(!has('customer_experience.read'))return <PermissionNote permission="customer_experience.read"/>;
 if(!data&&!err)return <Loading/>;
 const changePaths=deepDiffPaths(data?.published?.config||{},draft).filter(x=>x!=='schema_version');
 const font=catalog.typography_presets?.find(x=>x.key===draft.typography?.preset);
 const selectedTemplate=catalog.templates?.find(x=>x.key===templateChoice);
 const previewPage=pageForRoute(previewRoute);
 return <div className="customer-experience-page cx4-designer-page">
  <DesignerCommandBar data={data} draft={draft} dirty={dirty} saveState={saveState} savedAt={savedAt} busy={busy} changePaths={changePaths} undo={undo} redo={redo} undoStack={undoStack} redoStack={redoStack} openPublished={openPublished} save={save} publish={publish} has={has}/>
  <ErrorBox error={err}/>
  <div className="store-designer-scrollframe cx4-scrollframe">
   <div className="store-designer-shell cx4-shell">
    <DesignerNavigator active={active} setActive={setActive} draft={draft} previewRoute={previewRoute} setPreviewRoute={setPreviewRoute} selectedSectionId={selectedSectionId} setSelectedSectionId={setSelectedSectionId} productPreviewRoute={productPreviewRoute}/>
    <PreviewStudio previewPath={previewPath} previewRoute={previewRoute} previewPage={previewPage} draft={draft} mode={previewMode} setMode={setPreviewMode} zoom={zoom} setZoom={setZoom} frames={frames} openDraftPreview={openDraftPreview} issuePreview={issuePreview}/>
    <aside className="designer-inspector cx4-inspector"><Inspector active={active} setActive={setActive} previewPage={previewPage} changePaths={changePaths} draft={draft} data={data} catalog={catalog} font={font} templateChoice={templateChoice} setTemplateChoice={setTemplateChoice} selectedTemplate={selectedTemplate} keepContent={keepContent} setKeepContent={setKeepContent} applyTemplate={applyTemplate} mutate={mutate} update={update} updateNested={updateNested} setPicker={setPicker} rollback={rollback} dragIndex={dragIndex} setDragIndex={setDragIndex} selectedSectionId={selectedSectionId} setSelectedSectionId={setSelectedSectionId} previewProducts={previewProducts} previewProductRef={previewProductRef} previewProductError={previewProductError} choosePreviewProduct={choosePreviewProduct}/></aside>
   </div>
  </div>
  <MediaPicker open={!!picker} api={api} onClose={()=>setPicker(null)} mediaType={picker?.mediaType} onSelect={url=>{picker?.onSelect?.(url);setPicker(null)}}/>
  <Toast message={toast} onDone={()=>setToast('')}/>
 </div>;
}

function DesignerCommandBar({data,draft,dirty,saveState,savedAt,busy,changePaths,undo,redo,undoStack,redoStack,openPublished,save,publish,has}){
 return <header className="cx4-command-bar">
  <div className="cx4-command-context">
   <span className="cx4-command-kicker">Customer Experience</span>
   <div className="cx4-command-title"><h1>Store Designer</h1><span>v4</span></div>
   <div className="cx4-command-meta"><strong>{data?.store?.name||'Primary store'}</strong><span>{data?.storefront_path||'—'}</span><span>Schema v{draft.schema_version||4}</span><span>{templateLabel(data?.draft)}</span></div>
  </div>
  <div className="cx4-command-state" aria-label="Publishing state">
   <span><small>Live</small><strong>v{data?.published?.version||'—'}</strong></span>
   <span><small>Draft</small><strong>v{data?.draft?.version||'—'}</strong></span>
   <span className={`cx4-save-state ${saveState==='error'?'error':dirty?'dirty':'saved'}`}><i/>{saveLabel(saveState,dirty,savedAt)}</span>
  </div>
  <div className="cx4-command-actions">
   <div className="cx4-history-actions"><button type="button" aria-label="Undo" title="Undo (Ctrl/Cmd+Z)" disabled={!undoStack.length} onClick={undo}>↶</button><button type="button" aria-label="Redo" title="Redo (Ctrl/Cmd+Shift+Z)" disabled={!redoStack.length} onClick={redo}>↷</button></div>
   <VbenButton variant="secondary" size="sm" onClick={openPublished}>Open live</VbenButton>
   {has('customer_experience.manage')&&<VbenButton variant="secondary" size="sm" loading={busy&&saveState==='saving'} disabled={busy||(!dirty&&saveState!=='error')} onClick={()=>save().catch(()=>{})}>{saveState==='error'?'Retry save':'Save'}</VbenButton>}
   {has('customer_experience.publish')&&<VbenButton size="sm" loading={busy&&saveState!=='saving'} disabled={busy} onClick={publish}>Publish{changePaths.length?` · ${changePaths.length}`:''}</VbenButton>}
  </div>
 </header>
}

function DesignerNavigator({active,setActive,draft,previewRoute,setPreviewRoute,selectedSectionId,setSelectedSectionId,productPreviewRoute}){
 const groups=['Storefront','Commerce','Account'];const[query,setQuery]=useState('');const[collapsed,setCollapsed]=useState({});
 const selectPage=page=>{if(page.key==='product'){setActive('productDetail');if(productPreviewRoute)setPreviewRoute(productPreviewRoute);return}setPreviewRoute(page.route);setActive(page.route==='/'?'home':'page');if(page.route==='/'&&!selectedSectionId)setSelectedSectionId(draft.home?.sections?.[0]?.id||'')};
 const globals=designerPanels.filter(x=>x[0]!=='home'&&x[1].toLowerCase().includes(query.toLowerCase()));
 const pageActive=page=>page.key==='product'?String(previewRoute).startsWith('/product/'):previewRoute===page.route;
 return <aside className="designer-sections cx4-navigator">
  <div className="designer-panel-title cx4-navigator-head"><span>Navigator</span><strong>Storefront</strong><small>Pages + global design</small></div>
  <div className="cx4-nav-search"><VbenIcon name="search" size={13}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find page or setting" aria-label="Find page or setting"/></div>
  <div className="cx4-nav-scroll">
   <div className="cx4-nav-section-title">Pages</div>
   {groups.map(group=>{const pages=previewPages.filter(p=>p.group===group&&p.label.toLowerCase().includes(query.toLowerCase()));if(!pages.length)return null;const closed=collapsed[group]===true;return <div className={`cx4-page-group ${closed?'is-collapsed':''}`} key={group}><button type="button" className="cx4-page-group-toggle" onClick={()=>setCollapsed(x=>({...x,[group]:!x[group]}))}><span>{group}</span><b>{closed?'›':'⌄'}</b></button>{!closed&&pages.map(page=><button type="button" key={page.key} className={`cx4-page-node ${pageActive(page)?'active':''}`} onClick={()=>selectPage(page)}><i>{page.icon}</i><span><strong>{page.label}</strong><small>{page.key==='product'?(productPreviewRoute||'Choose a product'):page.route}</small></span>{pageActive(page)&&<b>●</b>}</button>)}</div>})}
   {!query&&previewRoute==='/'&&<div className="cx4-section-tree"><span>Home sections</span>{(draft.home?.sections||[]).map((section,index)=><button type="button" key={section.id||index} className={active==='home'&&selectedSectionId===(section.id||'')?'active':''} onClick={()=>{setActive('home');setSelectedSectionId(section.id||'')}}><i>{section.enabled===false?'○':'●'}</i><span>{section.title||sectionTypes.find(x=>x[0]===section.type)?.[1]||`Section ${index+1}`}</span></button>)}</div>}
   <div className="cx4-nav-divider"/>
   <div className="cx4-nav-section-title">Global design</div>
   <div className="cx4-global-list">{globals.map(([key,label,icon])=><button type="button" key={key} className={active===key?'active':''} onClick={()=>setActive(key)}><i>{icon}</i><span>{label}</span></button>)}</div>
   {query&&!globals.length&&!previewPages.some(p=>p.label.toLowerCase().includes(query.toLowerCase()))&&<div className="cx4-nav-empty">No designer setting matches “{query}”.</div>}
  </div>
 </aside>
}

function PreviewStudio({previewPath,previewRoute,previewPage,draft,mode,setMode,zoom,setZoom,frames,openDraftPreview,issuePreview}){
 const src=previewPath?`${CUSTOMER_WEB_BASE}${previewPath}?embed=designer&parent_origin=${encodeURIComponent(location.origin)}#${previewRoute}`:'';
 const modes=[['desktop','Desktop'],['tablet','Tablet'],['mobile','Mobile'],['both','Side by side']];
 return <section className="designer-preview cx4-preview">
  <div className="preview-toolbar cx4-preview-toolbar">
   <div className="cx4-preview-context"><span>Previewing</span><strong>{previewPage.label}</strong><small>{previewPage.route}</small></div>
   <div className="device-tabs">{modes.map(([v,l])=><button type="button" key={v} className={mode===v?'active':''} onClick={()=>setMode(v)}>{l}</button>)}</div>
   <div className="preview-tools"><select aria-label="Preview zoom" value={zoom} onChange={e=>setZoom(e.target.value)}><option value="fit">Fit</option><option value="50">50%</option><option value="67">67%</option><option value="75">75%</option><option value="90">90%</option><option value="100">100%</option></select><button type="button" onClick={openDraftPreview} disabled={!previewPath}>↗ Open</button><button type="button" onClick={issuePreview} aria-label="Refresh preview"><VbenIcon name="refresh" size={14}/></button></div>
  </div>
  <div className={`preview-canvas mode-${mode}`}>{!src?<div className="preview-loading"><span>Preparing secure preview…</span><button className="secondary" onClick={issuePreview}>Retry preview</button></div>:mode==='both'?<><DesignerFrame key={`desktop-${previewRoute}`} kind="desktop" src={src} zoom="fit" frames={frames} draft={draft}/><DesignerFrame key={`mobile-${previewRoute}`} kind="mobile" src={src} zoom="fit" frames={frames} draft={draft}/></>:<DesignerFrame key={`${mode}-${previewRoute}`} kind={mode} src={src} zoom={zoom} frames={frames} draft={draft}/>}</div>
  <div className="preview-foot cx4-preview-foot"><span><i/>Real Customer Web renderer</span><span>Secure draft token · live unsaved configuration</span></div>
 </section>
}
function DesignerFrame({kind,src,zoom,frames,draft}){const size=kind==='mobile'?{w:390,h:844}:kind==='tablet'?{w:768,h:1024}:{w:1440,h:900};const fit=kind==='desktop'?.52:kind==='tablet'?.65:.72;const manual={50:.5,67:.67,75:.75,90:.9,100:1};const scale=zoom==='fit'?fit:(manual[Number(zoom)]||fit);const ref=useCallback(node=>{if(node)frames.current.add(node)},[frames]);return <div className={`device-frame-wrap ${kind}`} style={{width:size.w*scale,height:size.h*scale}}><div className="device-label"><strong>{kind[0].toUpperCase()+kind.slice(1)}</strong><span>{size.w} × {size.h}</span></div><iframe ref={ref} title={`${kind} storefront preview`} src={src} referrerPolicy="no-referrer" style={{width:size.w,height:size.h,transform:`scale(${scale})`,transformOrigin:'top left'}} onLoad={e=>{frames.current.add(e.currentTarget);try{e.currentTarget.contentWindow?.postMessage({type:'luke-store-designer:config',config:draft},CUSTOMER_WEB_ORIGIN)}catch{}}}/></div>}

