function StoreIdentity({draft,data,update,mutate,setPicker}){const internal=data?.store?.name||'Primary store';return <><InspectorSection title="Names" description="Keep merchant/internal identity separate from what shoppers see."><div className="identity-readonly"><span>Internal store name</span><strong>{internal}</strong><small>Used inside Luke Shop merchant management.</small></div><label className="designer-check"><input type="checkbox" checked={draft.branding?.use_internal_name===true} onChange={e=>mutate(x=>{x.branding={...(x.branding||{}),use_internal_name:e.target.checked}})}/><span><strong>Use internal name on storefront</strong><small>When enabled, Customer Display Name follows the store record.</small></span></label><Field label="Customer display name"><input disabled={draft.branding?.use_internal_name===true} value={draft.branding?.store_name||''} onChange={e=>update('branding','store_name',e.target.value)} placeholder={internal}/></Field></InspectorSection><InspectorSection title="Brand media"><MediaField label="Logo" value={draft.branding?.logo_url} onChange={v=>update('branding','logo_url',v)} setPicker={setPicker}/><MediaField label="Favicon" value={draft.branding?.favicon_url} onChange={v=>update('branding','favicon_url',v)} setPicker={setPicker} mediaType="IMAGE"/></InspectorSection><InspectorSection title="Campaign copy"><Field label="Announcement"><input value={draft.branding?.announcement||''} onChange={e=>update('branding','announcement',e.target.value)}/></Field><Field label="Default hero title"><input value={draft.branding?.hero_title||''} onChange={e=>update('branding','hero_title',e.target.value)}/></Field><Field label="Default hero subtitle"><textarea value={draft.branding?.hero_subtitle||''} onChange={e=>update('branding','hero_subtitle',e.target.value)}/></Field></InspectorSection></>}
function HeaderPanel({draft,update,mutate,setPicker}){const enabled=draft.navigation||[];const toggle=(item,checked)=>mutate(x=>{const current=x.navigation||[];x.navigation=checked?[...new Set([...current,item])]:current.filter(v=>v!==item)});const move=(item,delta)=>mutate(x=>{const current=[...(x.navigation||[])];const from=current.indexOf(item),to=from+delta;if(from<0||to<0||to>=current.length)return;const[moved]=current.splice(from,1);current.splice(to,0,moved);x.navigation=current});return <div className="header-builder-a1"><InspectorSection title="Header layout" description="Uses the existing Storefront header schema; no navigation or account behavior is replaced."><Field label="Desktop header"><select value={draft.layout?.header||fallback.layout.header} onChange={e=>update('layout','header',e.target.value)}>{layouts.header.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="Mobile navigation"><select value={draft.layout?.mobile_nav||fallback.layout.mobile_nav} onChange={e=>update('layout','mobile_nav',e.target.value)}>{layouts.mobile_nav.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><div className="header-layout-preview" data-layout={draft.layout?.header||fallback.layout.header} aria-hidden="true"><i/><span/><span/><span/></div></InspectorSection><InspectorSection title="Brand & announcement"><MediaField label="Header logo" value={draft.branding?.logo_url} onChange={v=>update('branding','logo_url',v)} setPicker={setPicker}/><Field label="Announcement"><input value={draft.branding?.announcement||''} onChange={e=>update('branding','announcement',e.target.value)} placeholder="Optional storefront announcement"/></Field><label className="designer-check"><input type="checkbox" checked={draft.features?.search!==false} onChange={e=>mutate(x=>{x.features={...(x.features||{}),search:e.target.checked}})}/><span><strong>Show product search</strong><small>Controls the existing storefront search entry point.</small></span></label></InspectorSection><InspectorSection title="Primary navigation" description="Choose visible destinations and reorder the enabled items."><div className="header-nav-builder">{navItems.map(item=>{const on=enabled.includes(item),index=enabled.indexOf(item);return <div key={item} className={on?'enabled':'disabled'}><label><input type="checkbox" checked={on} onChange={e=>toggle(item,e.target.checked)}/><span><strong>{item[0].toUpperCase()+item.slice(1)}</strong><small>{on?`Position ${index+1}`:'Hidden from navigation'}</small></span></label><div><button type="button" disabled={!on||index<=0} onClick={()=>move(item,-1)} aria-label={`Move ${item} up`}>↑</button><button type="button" disabled={!on||index<0||index>=enabled.length-1} onClick={()=>move(item,1)} aria-label={`Move ${item} down`}>↓</button></div></div>})}</div></InspectorSection></div>}
function TemplatesPanel({catalog,templateChoice,setTemplateChoice,selectedTemplate,keepContent,setKeepContent,applyTemplate}){const[filter,setFilter]=useState('ALL');const types=['ALL',...new Set((catalog.templates||[]).map(t=>t.business_type))];const shown=(catalog.templates||[]).filter(t=>filter==='ALL'||t.business_type===filter);return <><InspectorSection title="Template library" description="Choose a starting design without replacing products."><div className="template-filter">{types.map(t=><button key={t} className={filter===t?'active':''} onClick={()=>setFilter(t)}>{t}</button>)}</div><div className="template-gallery-v3">{shown.map(t=><button key={t.key} className={templateChoice===t.key?'selected':''} onClick={()=>setTemplateChoice(t.key)}><div className="template-thumb" style={{'--tp':t.config?.theme?.primary||'#166534','--tb':t.config?.theme?.background||'#f8fafc'}}><i/><i/><span/></div><strong>{t.name}</strong><span>{t.business_type}</span><small>{t.config?.typography?.preset||'System'} · {t.config?.layout?.hero||'split'}</small></button>)}</div></InspectorSection>{selectedTemplate&&<InspectorSection title={`Apply ${selectedTemplate.name}`} description="Choose how much of the template to use."><label className="designer-check"><input type="checkbox" checked={keepContent} onChange={e=>setKeepContent(e.target.checked)}/><span><strong>Keep existing store content</strong><small>Preserve copy, media, navigation and commerce feature choices where safe.</small></span></label><div className="stack-actions"><button className="secondary" onClick={()=>applyTemplate('layout')}>Apply layout only</button><button className="secondary" onClick={()=>applyTemplate('theme')}>Apply theme + fonts</button><button className="primary" onClick={()=>applyTemplate('full')}>Use complete design</button></div></InspectorSection>}</>}
function ThemePanel({draft,update,mutate,catalog}){const packs=(catalog.status_visual_packs?.length?catalog.status_visual_packs:[{key:'AUTO',name:'Automatic'}]);return <><InspectorSection title="Order status visuals" description="Choose the customer-facing icon and timeline style. Automatic follows the selected storefront template."><Field label="Status visual pack"><select value={draft.status_visual_pack||'AUTO'} onChange={e=>mutate(x=>{x.status_visual_pack=e.target.value})}>{packs.map(x=>{const key=typeof x==='string'?x:x.key;const name=typeof x==='string'?(key==='AUTO'?'Automatic (template default)':key.replace(/_/g,' ')):(key==='AUTO'?'Automatic (template default)':x.name||key.replace(/_/g,' '));return <option key={key} value={key}>{name}</option>})}</select></Field><small className="inspector-hint">The order keeps semantic statuses such as OUT_FOR_DELIVERY. Platform Control Center owns approved icon mappings; this setting changes only Customer Web presentation.</small></InspectorSection><InspectorSection title="Color system"><div className="designer-color-grid">{themeFields.map(([k,l])=><Field key={k} label={l}><div className="designer-color"><input type="color" value={draft.theme?.[k]||fallback.theme[k]} onChange={e=>update('theme',k,e.target.value)}/><input value={draft.theme?.[k]||''} onChange={e=>update('theme',k,e.target.value)}/></div></Field>)}</div></InspectorSection><InspectorSection title="Surfaces & controls"><Field label="Corner radius"><select value={draft.theme?.radius||'medium'} onChange={e=>update('theme','radius',e.target.value)}><option value="small">Compact</option><option value="medium">Balanced</option><option value="large">Soft</option><option value="xl">Extra soft</option></select></Field><Field label="Card style"><select value={draft.theme?.card_style||'clean'} onChange={e=>update('theme','card_style',e.target.value)}>{['clean','soft','editorial','bold','technical'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Button style"><select value={draft.theme?.button_style||'solid'} onChange={e=>update('theme','button_style',e.target.value)}>{['solid','pill','outline','soft'].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Density"><select value={draft.theme?.density||'comfortable'} onChange={e=>update('theme','density',e.target.value)}><option>compact</option><option>comfortable</option><option>spacious</option></select></Field></InspectorSection></>}
